provider "aws" {
  region              = var.region
  allowed_account_ids = [var.expected_account_id]
  default_tags {
    tags = {
      project           = "ascc-lab"
      "ascc:run"        = "spike"
      "ascc:managed-by" = "terraform"
    }
  }
}

resource "aws_s3_bucket" "datalake_raw" {
  # Bucket names are global: fixture's "datalake-raw" cannot be reused as-is.
  bucket        = "datalake-raw-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
  tags = {
    Name               = "datalake-raw"
    DataClassification = "PII"
  }
}

resource "aws_iam_role" "datalake_etl_role" {
  name = "datalake-etl-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

