resource "aws_security_group" "datalake_etl_sg" {
  name        = "datalake-etl-sg"
  description = "ASCC spike: SSH open to internet by design; sshd disabled on host"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description = "Deliberate leak: SSH from anywhere"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "HTTPS only (SSM agent, package repos)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "datalake-etl-sg" }
}

